describe('Checkout Form Mobile Responsiveness', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.viewport('iphone-x');
  });

  it('should stack form fields vertically on mobile screens', () => {
    cy.get('[data-testid="checkout-form"]').should('exist');

    cy.get('[data-testid="form-field-email"]').then(($email) => {
      const emailTop = $email[0].getBoundingClientRect().top;
      const emailLeft = $email[0].getBoundingClientRect().left;

      cy.get('[data-testid="form-field-name"]').then(($name) => {
        const nameTop = $name[0].getBoundingClientRect().top;
        const nameLeft = $name[0].getBoundingClientRect().left;

        expect(nameTop).to.be.greaterThan(emailTop);
        expect(Math.abs(nameLeft - emailLeft)).to.be.lessThan(10);
      });
    });

    cy.get('[data-testid="form-field-address"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="form-field-city"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="form-field-zip"]').should('have.css', 'display', 'block');
  });

  it('should display form fields at full width on mobile', () => {
    cy.get('[data-testid="checkout-form"]').then(($form) => {
      const formWidth = $form[0].getBoundingClientRect().width;

      cy.get('[data-testid="form-field-email"]').then(($field) => {
        const fieldWidth = $field[0].getBoundingClientRect().width;
        expect(fieldWidth).to.be.closeTo(formWidth, 5);
      });

      cy.get('[data-testid="form-field-name"]').then(($field) => {
        const fieldWidth = $field[0].getBoundingClientRect().width;
        expect(fieldWidth).to.be.closeTo(formWidth, 5);
      });
    });
  });

  it('should maintain vertical stacking with form validation errors on mobile', () => {
    cy.get('[data-testid="checkout-submit"]').click();

    cy.get('[data-testid="form-field-email"]').should('have.attr', 'aria-invalid', 'true');
    cy.get('[data-testid="error-email"]').should('be.visible');

    cy.get('[data-testid="form-field-email"]').then(($email) => {
      const emailTop = $email[0].getBoundingClientRect().top;

      cy.get('[data-testid="form-field-name"]').then(($name) => {
        const nameTop = $name[0].getBoundingClientRect().top;
        expect(nameTop).to.be.greaterThan(emailTop);
      });
    });
  });

  it('should reflow to horizontal layout on desktop screens', () => {
    cy.viewport(1280, 720);

    cy.get('[data-testid="form-field-email"]').then(($email) => {
      const emailTop = $email[0].getBoundingClientRect().top;
      const emailLeft = $email[0].getBoundingClientRect().left;

      cy.get('[data-testid="form-field-name"]').then(($name) => {
        const nameTop = $name[0].getBoundingClientRect().top;
        const nameLeft = $name[0].getBoundingClientRect().left;

        expect(nameTop).to.equal(emailTop);
        expect(nameLeft).to.be.greaterThan(emailLeft);
      });
    });
  });

  it('should handle long text content without breaking layout on mobile', () => {
    cy.get('[data-testid="form-field-address"]').type('123 Very Long Street Name That Might Wrap Across Multiple Lines');

    cy.get('[data-testid="form-field-address"]').should('have.css', 'word-wrap', 'break-word');
    cy.get('[data-testid="form-field-address"]').then(($field) => {
      const fieldHeight = $field[0].getBoundingClientRect().height;
      expect(fieldHeight).to.be.greaterThan(0);
    });
  });
});
